input.command:
time timeout 600 duckdb bench.duckdb -csv -c "
LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;

CREATE OR REPLACE TABLE field_parcel_pairs AS
SELECT f.field_id, p.cod_imovel,
       ST_Area(ST_Intersection(f.geometry, p.geometry)) as inter_area,
       ST_Area(f.geometry) as field_area
FROM fields_in_envelope f
JOIN listed_parcels p ON ST_Intersects(f.geometry, p.geometry)
WHERE ST_Area(ST_Intersection(f.geometry, p.geometry)) > 0;

SELECT count(*) FROM field_parcel_pairs;
" 2>&1

timeout 600 duckdb bench.duckdb -csv -c "
LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;

CREATE OR REPLACE TABLE field_single AS
SELECT field_id,
  max(inter_area/field_area) as max_single_frac
FROM field_parcel_pairs
GROUP BY field_id;

SELECT count(*) FROM field_single;
SELECT count(*) FROM field_single WHERE max_single_frac >= 0.667;
"

timeout 600 duckdb bench.duckdb -csv -c "
LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;

CREATE OR REPLACE TABLE field_primary AS
WITH ranked AS (
  SELECT fp.field_id, fp.cod_imovel, fp.inter_area/fp.field_area as frac, fs.max_single_frac
  FROM field_parcel_pairs fp
  JOIN field_single fs ON fs.field_id = fp.field_id
  WHERE fp.inter_area/fp.field_area >= fs.max_single_frac - 1e-9
)
SELECT field_id, min(cod_imovel) as primary_cod_imovel, max(max_single_frac) as max_single_frac
FROM ranked
GROUP BY field_id;

SELECT count(*) FROM field_primary;
"

timeout 120 duckdb bench.duckdb -csv -c "
LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;
SELECT ST_AsText(ST_Transform(ST_GeomFromText('POINT(-51.3 -15.5)'), 'EPSG:4326','EPSG:5880'));
" 2>&1

time timeout 600 duckdb bench.duckdb -csv -c "
LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;

CREATE OR REPLACE TABLE listed_parcels_5880 AS
SELECT cod_imovel, ST_Transform(geometry, 'EPSG:4326', 'EPSG:5880', true) as geom_5880
FROM listed_parcels;

CREATE OR REPLACE TABLE dissolved_buffer_5880 AS
SELECT ST_Union_Agg(ST_Buffer(geom_5880, 25)) as geom FROM listed_parcels_5880;

CREATE OR REPLACE TABLE dissolved_buffer_4326 AS
SELECT ST_Transform(geom, 'EPSG:5880', 'EPSG:4326', true) as geom FROM dissolved_buffer_5880;

SELECT ST_Area(geom) FROM dissolved_buffer_4326;
" 2>&1

time timeout 600 duckdb bench.duckdb -csv -c "
LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;

CREATE OR REPLACE TABLE field_aggregate AS
SELECT f.field_id,
  ST_Area(ST_Intersection(f.geometry, db.geom)) / ST_Area(f.geometry) as union_frac
FROM fields_in_envelope f, dissolved_buffer_4326 db
WHERE ST_Intersects(f.geometry, db.geom);

SELECT count(*) FROM field_aggregate;
SELECT count(*) FROM field_aggregate WHERE union_frac >= 0.667;
" 2>&1

timeout 600 duckdb bench.duckdb -csv -c "
LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;

CREATE OR REPLACE TABLE field_match AS
SELECT
  coalesce(fs.field_id, fa.field_id) as field_id,
  fs.max_single_frac,
  fa.union_frac,
  (fs.max_single_frac >= 0.667) as pass_single,
  (fa.union_frac >= 0.667) as pass_aggregate
FROM field_single fs
FULL OUTER JOIN field_aggregate fa ON fs.field_id = fa.field_id;

SELECT count(*) FROM field_match;
SELECT count(*) FROM field_match WHERE pass_single OR pass_aggregate;
"

timeout 600 duckdb bench.duckdb -csv -c "
LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;
SELECT count(*) as single_not_agg FROM field_match WHERE pass_single AND NOT coalesce(pass_aggregate,false);
SELECT count(*) as agg_not_single FROM field_match WHERE pass_aggregate AND NOT coalesce(pass_single,false);
SELECT count(*) as both FROM field_match WHERE pass_single AND pass_aggregate;
SELECT count(*) as neither_but_touch FROM field_match WHERE NOT coalesce(pass_single,false) AND NOT coalesce(pass_aggregate,false);
"

timeout 600 duckdb bench.duckdb -csv -c "
LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;
SELECT field_id, max_single_frac, union_frac FROM field_match WHERE pass_aggregate AND NOT coalesce(pass_single,false) ORDER BY max_single_frac NULLS FIRST LIMIT 30;
"

timeout 600 duckdb bench.duckdb -csv -c "
LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;
SELECT min(max_single_frac) as min_single_frac, avg(max_single_frac) as avg_single_frac, avg(union_frac) as avg_union_frac
FROM field_match WHERE pass_single OR pass_aggregate;
"

timeout 600 duckdb bench.duckdb -csv -c "
LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;
SELECT count(*) as n_excluded FROM field_match
WHERE max_single_frac IS NOT NULL AND NOT coalesce(pass_single,false) AND NOT coalesce(pass_aggregate,false);
"

timeout 600 duckdb bench.duckdb -csv -c "
LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;

CREATE OR REPLACE TABLE matched_fields AS
SELECT fm.field_id, fm.max_single_frac, fm.union_frac, fp.primary_cod_imovel
FROM field_match fm
JOIN field_primary fp ON fp.field_id = fm.field_id
WHERE fm.pass_single OR fm.pass_aggregate;

SELECT count(*) FROM matched_fields;

SELECT primary_cod_imovel, count(*) as n_fields
FROM matched_fields
GROUP BY 1
ORDER BY n_fields DESC, primary_cod_imovel ASC
LIMIT 10;
"

time timeout 600 duckdb bench.duckdb -csv -c "
LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;

CREATE OR REPLACE TABLE matched_fields_geom AS
SELECT mf.field_id, mf.primary_cod_imovel, mf.max_single_frac, mf.union_frac, f.geometry,
  f.mbmode24, f.deforestarea0104, f.deforestarea0509, f.deforestarea1014, f.deforestarea1520, f.deforestarea2124,
  f.mode_year, f.firstyear, f.firstyearmajority, f.hansen_covered_area, f.hansen_loss_area
FROM matched_fields mf
JOIN fields_in_envelope f ON f.field_id = mf.field_id;

SELECT count(*) FROM matched_fields_geom;

CREATE OR REPLACE TABLE matched_fields_area AS
SELECT field_id, primary_cod_imovel,
  ST_Area(ST_Transform(geometry, 'EPSG:4326','EPSG:5880', true)) / 10000.0 as area_ha
FROM matched_fields_geom;

SELECT sum(area_ha) as matched_field_ha FROM matched_fields_area;
" 2>&1

timeout 600 duckdb bench.duckdb -csv -c "
