"

timeout 600 duckdb bench.duckdb -csv -c "
LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;
SELECT
  count(distinct primary_cod_imovel) as n_parcels,
  count(*) as n_fields,
  sum(deforestarea2124)/10000.0 as post2020_loss_ha,
  count(*) filter (where deforestarea2124 > 0) as fields_with_post2020_loss
FROM matched_fields_geom;
