timeout 600 duckdb bench.duckdb -csv -c "
LOAD spatial; LOAD httpfs;
SET geometry_always_xy = true;

CREATE OR REPLACE TABLE facilities_pt_5880 AS
SELECT entity_id, tier, ST_Transform(geometry,'EPSG:4326','EPSG:5880', true) as geom5880
FROM facilities WHERE tier IN ('slaughter_point','intake_point','mill_point');

CREATE OR REPLACE TABLE flagged_centroid_5880 AS
SELECT cod_imovel, ST_Transform(centroid,'EPSG:4326','EPSG:5880', true) as c5880
FROM flagged_parcel_geom;

CREATE OR REPLACE TABLE q26_tbl AS
WITH parcel_tier AS (
  SELECT q.cod_imovel, unnest(string_split(q.routed_tier,'|')) as tier
  FROM q24_tbl q WHERE q.routed_tier NOT IN ('no_tier','unknown')
), joined AS (
  SELECT pt.cod_imovel, pt.tier, f.entity_id,
    ST_Distance(fc.c5880, f.geom5880)/1000.0 as distance_km
  FROM parcel_tier pt
  JOIN flagged_centroid_5880 fc ON fc.cod_imovel = pt.cod_imovel
  JOIN facilities_pt_5880 f ON f.tier = pt.tier
), ranked AS (
  SELECT *, row_number() OVER (PARTITION BY cod_imovel ORDER BY distance_km ASC, entity_id ASC) as rn
  FROM joined
)
SELECT cod_imovel, entity_id, tier, distance_km FROM ranked WHERE rn=1;

SELECT * FROM q26_tbl ORDER BY cod_imovel;
"

