CREATE OR REPLACE TABLE delivery_candidates_all AS
WITH parcel_tier AS (
  SELECT q.cod_imovel, unnest(string_split(q.routed_tier,'|')) as tier
  FROM q24_tbl q WHERE q.routed_tier NOT IN ('no_tier','unknown','')
)
SELECT pt.cod_imovel, pt.tier, f.entity_id, f.weight, f.basis,
  ST_Distance(fc.c5880, f.geom5880)/1000.0 as distance_km
FROM parcel_tier pt
JOIN flagged_centroid_5880 fc ON fc.cod_imovel = pt.cod_imovel
JOIN facilities_5880_all f ON f.tier = pt.tier
WHERE (pt.tier != 'intake_point' OR f.weight >= 1000);

SELECT count(*) FROM delivery_candidates_all;
SELECT cod_imovel, count(*) filter (where distance_km<=100) as within_100
FROM delivery_candidates_all GROUP BY 1 ORDER BY 1;
